H.background();
const v = H.plot2d({ xMin: -6, xMax: 6, yMin: -4, yMax: 4 });
v.grid(); v.axes();
const k = 9e9;
const qp = P.qp * 1e-9, qn = -P.qn * 1e-9, d = P.d;
const cp = [d, 0], cn = [-d, 0];
const eps = 0.15;
const potAt = (x, y) => {
  const rp = Math.max(eps, Math.hypot(x - cp[0], y - cp[1]));
  const rn = Math.max(eps, Math.hypot(x - cn[0], y - cn[1]));
  return k * qp / rp + k * qn / rn; // volts (charges in nC over metres)
};
// Draw equipotential contours by marching a coarse grid and connecting cells
// whose potential is near each chosen level (dotted level set, color by sign).
const levels = [-300, -150, -60, 60, 150, 300];
const nx = 120, ny = 80;
for (let li = 0; li < levels.length; li++) {
  const L = levels[li];
  const col = L > 0 ? H.colors.warn : H.colors.accent;
  for (let i = 0; i < nx; i++) {
    for (let j = 0; j < ny; j++) {
      const x = -6 + 12 * i / nx, y = -4 + 8 * j / ny;
      const Vc = potAt(x, y);
      const Vr = potAt(x + 12 / nx, y);
      const Vu = potAt(x, y + 8 / ny);
      // a contour at level L passes through this cell if L is bracketed
      if ((Vc - L) * (Vr - L) < 0 || (Vc - L) * (Vu - L) < 0) {
        v.dot(x, y, { r: 1.4, fill: col });
      }
    }
  }
}
// the two source charges
v.circle(cp[0], cp[1], 9, { fill: H.colors.warn, stroke: H.colors.ink, width: 1.5 });
v.circle(cn[0], cn[1], 9, { fill: H.colors.accent, stroke: H.colors.ink, width: 1.5 });
v.text("+", cp[0], cp[1] - 0.05, { color: H.colors.ink, size: 13, align: "center", baseline: "middle", weight: 700 });
v.text("−", cn[0], cn[1] - 0.05, { color: H.colors.ink, size: 13, align: "center", baseline: "middle", weight: 700 });
// a test charge orbiting on roughly an equipotential ring, with the E-field
// arrow (always PERPENDICULAR to equipotentials) drawn at its location
const ang = t * 0.7;
const R = 2.4;
const tx = R * Math.cos(ang), ty = 1.6 * Math.sin(ang);
// numeric gradient of V -> E = -grad V
const h = 0.05;
const Ex = -(potAt(tx + h, ty) - potAt(tx - h, ty)) / (2 * h);
const Ey = -(potAt(tx, ty + h) - potAt(tx, ty - h)) / (2 * h);
const Emag = Math.hypot(Ex, Ey) || 1;
const al = 1.3;
v.arrow(tx, ty, tx + al * Ex / Emag, ty + al * Ey / Emag, { color: H.colors.good, width: 2.5, head: 9 });
v.dot(tx, ty, { r: 5, fill: H.colors.yellow });
const Vhere = potAt(tx, ty);
H.text("Equipotential lines + field E ⟂ V", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("V(test) = " + Vhere.toFixed(0) + " V    |E| = " + Emag.toFixed(0) + " V/m    (E points downhill in V)", 24, 52, { color: H.colors.sub, size: 13 });
H.legend([{ label: "V > 0", color: H.colors.warn }, { label: "V < 0", color: H.colors.accent }, { label: "E field", color: H.colors.good }], H.W - 130, 28);
